function validate([cost, target]) {
  if (!Array.isArray(cost) || cost.length !== 9) return 'cost needs exactly 9 values.';
  if (cost.some(c => !Number.isInteger(c) || c < 1 || c > 5000)) return 'Each cost is an integer from 1 to 5000.';
  if (!Number.isInteger(target) || target < 1 || target > 5000) return 'target is an integer from 1 to 5000.';
  return null;
}

