function largestNumber(cost, target) {
  const dp = new Array(target + 1).fill(-1);
  dp[0] = 0;
  for (let total = 1; total <= target; total++) {
    for (let digit = 1; digit <= 9; digit++) {
      const price = cost[digit - 1];
      if (price <= total && dp[total - price] >= 0) {
        dp[total] = Math.max(dp[total], dp[total - price] + 1);
      }
    }
  }
  if (dp[target] < 0) return "0";

  const digits = [];
  let remaining = target;
  for (let digit = 9; digit >= 1; digit--) {
    const price = cost[digit - 1];
    while (price <= remaining && dp[remaining - price] === dp[remaining] - 1) {
      digits.push(digit);
      remaining -= price;
    }
  }
  return digits.join("");
}

