function largestNumber(cost, target) {
  // Try every multiset of digits with total cost exactly target; the best number lists its digits in descending order.
  let best = "0";
  const counts = new Array(10).fill(0);
  const larger = (a, b) => a.length !== b.length ? a.length > b.length : a > b;
  function choose(digit, left) {
    if (digit === 0) {
      if (left !== 0) return;
      let text = "";
      for (let d = 9; d >= 1; d--) text += String(d).repeat(counts[d]);
      if (text.length > 0 && (best === "0" || larger(text, best))) best = text;
      return;
    }
    for (let times = 0; times * cost[digit - 1] <= left; times++) {
      counts[digit] = times;
      choose(digit - 1, left - times * cost[digit - 1]);
    }
    counts[digit] = 0;
  }
  choose(9, target);
  return best;
}

