function generate(rand, size) {
  if (size === 'large') {
    const top = [20, 300, 5000][Math.floor(rand() * 3)];
    const cost = Array.from({ length: 9 }, () => 1 + Math.floor(rand() * top));
    return [cost, 4000 + Math.floor(rand() * 1001)];
  }
  const top = [3, 8, 20][Math.floor(rand() * 3)];
  const cost = Array.from({ length: 9 }, () => 1 + Math.floor(rand() * top));
  if (rand() < 0.2) cost.fill(2 + Math.floor(rand() * 3));
  return [cost, 1 + Math.floor(rand() * 16)];
}
